'use client';
import { useState } from 'react';
import { useRouter } from 'next/navigation';
import { useUser } from '@/context/UserContext';
import { supabaseClient } from '@/lib/supabaseClient';
import Link from 'next/link';
import Loader from '@/components/Loader';

export default function LoginPage() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loginLoading, setLoginLoading] = useState(false);
  const [resendLoading, setResendLoading] = useState(false);
  const router = useRouter();
  const { fetchUserProfile } = useUser();

  const handleLogin = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setError('');
    setLoginLoading(true);
    try {
      const { data: authData, error: authError } = await supabaseClient.auth.signInWithPassword({ email, password });
      if (authError) { setError(authError.message); setLoginLoading(false); return; }
      const res = await fetch('http://localhost:5001/api/auth/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password }),
        credentials: 'include', 
      });
      if (!res.ok) { const errData = await res.json(); setError(errData.error || 'Login failed'); setLoginLoading(false); return; }
      const data = await res.json();
      await fetchUserProfile();
      if (data.is_admin) { window.location.href = '/admin/dashboard'; } else { router.push('/'); }
    } catch (err: any) { setError('Unexpected error occurred'); } finally { setLoginLoading(false); }
  };

  const handleResendConfirmation = async () => {
    setResendLoading(true);
    try {
      const { error } = await fetch(`${process.env.NEXT_PUBLIC_SUPABASE_URL}/auth/v1/admin/resend`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email }),
      }).then(r => r.json());
      if (error) { alert('Please enter a valid email.'); } else { alert('Confirmation email sent!'); }
    } catch (err: any) { alert('Unexpected error: ' + err.message); } finally { setResendLoading(false); }
  };

  return (
    <div className="relative min-h-screen w-full flex items-center justify-center custom-img p-4">
      <div className="absolute inset-0 bg-red-950/50 backdrop-blur-md z-10" />
      <div className="relative z-20 w-full max-w-md bg-white rounded-2xl shadow-2xl overflow-hidden">
        <div className="bg-red-700 py-8 text-center text-white">
          <h2 className="text-3xl font-black uppercase tracking-tighter">Welcome Back</h2>
          <p className="text-red-100 text-sm opacity-80">Sindjelic FC Portal</p>
        </div>
        <form className="p-8 space-y-6" onSubmit={handleLogin}>
          <input type="email" placeholder="Email Address" value={email} onChange={(e) => setEmail(e.target.value)} 
                 className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-lg outline-none focus:ring-2 focus:ring-red-600 transition" required />
          <input type="password" placeholder="Password" value={password} onChange={(e) => setPassword(e.target.value)} 
                 className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-lg outline-none focus:ring-2 focus:ring-red-600 transition" required />
          <button type="submit" className="w-full py-4 bg-red-600 text-white font-black uppercase tracking-widest rounded-lg hover:bg-red-700 transition shadow-lg shadow-red-600/20">
            {loginLoading ? <Loader /> : 'Sign In'}
          </button>
          {error && <p className="text-red-600 text-center text-xs font-bold">{error}</p>}
          <p className="text-center text-sm text-gray-500">
            Don't have an account? <Link href="/signup" className="text-red-700 font-bold hover:underline">Sign up</Link>
          </p>
        </form>
        <div className="px-8 pb-8 text-center border-t border-gray-100 pt-6">
          <p className="text-xs text-gray-400 mb-3">Haven't authorized your email yet?</p>
          <button onClick={handleResendConfirmation} className="text-xs font-bold text-red-600 hover:text-red-800 transition uppercase tracking-wider">
            {resendLoading ? <Loader /> : 'Resend Confirmation Email'}
          </button>
        </div>
      </div>
    </div>
  );
}